// SPDX-License-Identifier: GPL-3.0-or-later
//! Art replacement (`skin-definition.md` §6, §7; D2, D7, D12, D16, D18, D25–D27): the
//! invariants SP11–SP13, SP17, SP20, SP24–SP28 and the TGA example of §12.4, with skin
//! folders and image files generated by the tests in temporary directories.

mod skin_common;

use std::path::Path;
use std::sync::Arc;

use skin_common::{WarnCounter, dds, resolver, tga_raw, tga_solid, tga32, write};
use tessera_material::ui_image::{SourceTag, UiImageError, placeholder};
use tessera_ui::paint::{
    CanvasSet, CompositeOp, DisplayList, ImageLayer, PaintOp, Rect, paint_rect,
};
use tessera_ui::skin::{
    BaseTable, GameSkin, ImageChoice, LoadRequest, SkinEnvironment, SkinFileLedger, SkinImageError,
    SkinPathError, SkinSelection, SkinSet, SkinTables, resolve_image, skin_file,
};

const ART_FRAME: u32 = 0x1000_0001;
const ART_BUTTON: u32 = 0x1000_0002;
const ART_OTHER: u32 = 0x1000_0003;
const DID_FRAME: u32 = 0x4100_1000;
const DID_BUTTON: u32 = 0x4100_2000;
const DID_OTHER: u32 = 0x4100_3000;
const DID_GAME: u32 = 0x4100_9000;

fn tables() -> SkinTables {
    let (art_assets, elements) = resolver(
        &[
            ("Frame_TopLeft", ART_FRAME),
            ("Button_Normal", ART_BUTTON),
            ("Other_Art", ART_OTHER),
        ],
        &[],
    );
    let mut base = BaseTable::new();
    base.insert(DID_FRAME, ART_FRAME);
    base.insert(DID_BUTTON, ART_BUTTON);
    base.insert(DID_OTHER, ART_OTHER);
    SkinTables {
        art_assets,
        elements,
        base,
        ..SkinTables::default()
    }
}

fn selection(root: &Path) -> SkinSelection {
    let t = tables();
    let set = SkinSet::discover(root, &t);
    SkinSelection::new(Arc::new(set), Arc::new(t), SkinEnvironment::default())
}

fn file_of<'a>(choice: &ImageChoice<'a>) -> &'a tessera_ui::skin::SkinFile {
    match choice {
        ImageChoice::SkinFile(r) => r.file.as_ref().expect("usable path"),
        other => panic!("expected a skin file, got {other:?}"),
    }
}

#[test]
fn sp11_user_skin_over_game_skin_and_no_fallback() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="S"/><Mapping ArtAssetID="frame_topleft" FileName="art\missing.tga"/></opt>"#,
    );
    let sel = {
        let mut s = selection(tmp.path());
        s.apply_option("S");
        s
    };
    let overlay = sel.active().unwrap();
    let mut game = GameSkin::new("game", 1);
    game.insert(ART_FRAME, DID_GAME);
    let choice = resolve_image(
        DID_FRAME,
        &overlay.tables().base,
        Some(overlay.replacements()),
        Some(&game),
    );
    let file = file_of(&choice);
    assert_eq!(file.load().unwrap_err(), SkinImageError::NotFound);
    // The game skin applies where the user skin has no mapping.
    let mut game2 = GameSkin::new("game", 1);
    game2.insert(ART_BUTTON, DID_GAME);
    assert_eq!(
        resolve_image(
            DID_BUTTON,
            &overlay.tables().base,
            Some(overlay.replacements()),
            Some(&game2)
        ),
        ImageChoice::GameSkin {
            did: DID_GAME,
            art_asset: ART_BUTTON
        }
    );
    // A DID outside the base table is never substituted.
    assert_eq!(
        overlay.resolve_image(0x4100_7777),
        ImageChoice::Base(0x4100_7777)
    );
}

#[test]
fn sp12_placeholder_texels() {
    let p = placeholder();
    assert_eq!((p.width(), p.height()), (32, 32));
    let slate = 0xFF4C_4C66; // (76, 76, 102, 255)
    let white = 0xFFFF_FFFF;
    assert_eq!(p.pixel(0, 0), Some(slate));
    assert_eq!(p.pixel(28, 28), Some(slate));
    assert_eq!(p.pixel(29, 0), Some(white));
    assert_eq!(p.pixel(0, 29), Some(white));
    assert_eq!(p.pixel(31, 31), Some(white));
}

#[test]
fn sp13_and_example_12_4_tga_row_order() {
    let tmp = tempfile::tempdir().unwrap();
    let px = |x: u32, y: u32| 0xFF00_0000 | (x << 8) | y;
    write(&tmp.path().join("bu.tga"), &tga32(2, 2, false, px));
    write(&tmp.path().join("td.tga"), &tga32(2, 2, true, px));
    let mut rtl = tga32(2, 2, true, px);
    rtl[17] |= 0x10; // right-to-left bit: ignored
    write(&tmp.path().join("rtl.tga"), &rtl);
    let load = |n: &str| skin_file(tmp.path(), n, None).unwrap().load().unwrap();
    let (a, b, c) = (load("bu.tga"), load("td.tga"), load("rtl.tga"));
    assert_eq!(a.pixels(), b.pixels());
    assert_eq!(b.pixels(), c.pixels());
    assert_eq!(a.pixels(), &[px(0, 0), px(1, 0), px(0, 1), px(1, 1)]);
    // §12.4: the same bytes with descriptor 0x08 and 0x28 swap the rows.
    let mut bytes = tga32(2, 2, true, px);
    write(&tmp.path().join("raw28.tga"), &bytes);
    bytes[17] = 0x08;
    write(&tmp.path().join("raw08.tga"), &bytes);
    let (top, bottom) = (load("raw28.tga"), load("raw08.tga"));
    assert_eq!(top.pixels()[..2], bottom.pixels()[2..]);
    assert_eq!(top.pixels()[2..], bottom.pixels()[..2]);
}

#[test]
fn sp17_and_example_12_6_dds_sizes() {
    let tmp = tempfile::tempdir().unwrap();
    let fourcc = 0x4;
    let ok = |name: &str, bytes: Vec<u8>| {
        write(&tmp.path().join(name), &bytes);
        skin_file(tmp.path(), name, None).unwrap().load()
    };
    assert!(ok("a.dds", dds(8, 8, 0, fourcc, b"DXT1", 0, [0; 4], &[0; 32])).is_ok());
    assert!(ok("b.dds", dds(8, 8, 32, fourcc, b"DXT1", 0, [0; 4], &[0; 32])).is_ok());
    assert!(ok("c.dds", dds(8, 8, 31, fourcc, b"DXT1", 0, [0; 4], &[0; 32])).is_err());
    assert!(ok("d.dds", dds(8, 8, 0, fourcc, b"DXT1", 0, [0; 4], &[0; 31])).is_err());
    assert!(matches!(
        ok("e.dds", dds(6, 6, 0, fourcc, b"DXT1", 0, [0; 4], &[0; 32])),
        Err(SkinImageError::Decode(
            UiImageError::DxtNotMultipleOf4 { .. }
        ))
    ));
    assert!(ok("f.dds", dds(1, 1, 0, fourcc, b"DXT1", 0, [0; 4], &[0; 8])).is_err());
    let argb = [0x00FF_0000, 0x0000_FF00, 0x0000_00FF, 0xFF00_0000];
    let mut weird = dds(4, 4, 999, 0x41, b"\0\0\0\0", 0x120, argb, &[0x7F; 64]);
    weird[4..8].copy_from_slice(&7u32.to_le_bytes()); // header size not checked
    weird[28..32].copy_from_slice(&9u32.to_le_bytes()); // mip count ignored
    let img = ok("g.dds", weird).unwrap();
    assert_eq!((img.width(), img.height()), (4, 4));
    assert_eq!(img.tag(), SourceTag::Argb32);
    let img = ok("h.dds", dds(3, 5, 0, 0x41, b"\0\0\0\0", 32, argb, &[1; 60])).unwrap();
    assert_eq!((img.width(), img.height()), (3, 5));
}

#[test]
fn sp20_refresh_and_switching() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="Blue"/><Mapping ArtAssetID="Button_Normal" FileName="art/b.tga"/></opt>"#,
    );
    write(
        &tmp.path().join("S/art/b.tga"),
        &tga_solid(4, 4, 0xFF00_00FF),
    );
    let mut sel = selection(tmp.path());
    // No skin: the element shows its DID.
    assert!(sel.active().is_none());
    let sw = sel.apply_option("blue");
    let overlay = sw.current.clone().unwrap();
    // After activation, the refresh re-sets the base image from the original DID.
    let choice = overlay.resolve_image(DID_BUTTON);
    let img = file_of(&choice).load().unwrap();
    assert_eq!(img.pixel(0, 0), Some(0xFF00_00FF));
    assert_eq!(
        overlay.resolve_image(DID_FRAME),
        ImageChoice::Base(DID_FRAME)
    );
    // Deactivation: the client drops this overlay's files from the cache and re-sets the
    // DID again; the overlay it held is reported as `previous`.
    let off = sel.deactivate();
    assert!(off.current.is_none());
    let previous = off.previous.unwrap();
    assert_eq!(previous.files().len(), 1);
    assert_ne!(previous.generation(), sel.generation());
    // An unknown name leaves no skin active.
    let sw = sel.apply_option("no such skin");
    assert!(sw.current.is_none());
    assert_eq!(sw.not_found.as_deref(), Some("no such skin"));
}

fn paint(image: &Arc<tessera_material::ui_image::UiImage>, w: u32, h: u32) -> CanvasSet {
    let elem = Rect::from_xywh(0, 0, w, h);
    let mut list = DisplayList::new();
    list.push(PaintOp::Image(ImageLayer {
        rect: elem,
        clip: elem,
        anchor: [0, 0],
        image: Arc::clone(image),
        op: CompositeOp::Replace,
        opacity: 255,
    }))
    .unwrap();
    let mut c = CanvasSet::new(w, h).unwrap();
    paint_rect(&list, &mut c, elem);
    c
}

#[test]
fn sp24_native_size_tiled_and_clipped() {
    let tmp = tempfile::tempdir().unwrap();
    let px = |x: u32, y: u32| 0xFF00_0000 | (x << 16) | (y << 8) | 0x11;
    write(&tmp.path().join("small.tga"), &tga32(4, 4, true, px));
    write(&tmp.path().join("big.tga"), &tga32(40, 40, true, px));
    let small = Arc::new(
        skin_file(tmp.path(), "small.tga", None)
            .unwrap()
            .load()
            .unwrap(),
    );
    let c = paint(&small, 10, 6);
    assert_eq!(c.below().pixel(5, 5), px(1, 1));
    assert_eq!(c.below().pixel(9, 5), px(1, 1));
    assert_eq!(c.below().pixel(8, 4), px(0, 0));
    let big = Arc::new(
        skin_file(tmp.path(), "big.tga", None)
            .unwrap()
            .load()
            .unwrap(),
    );
    let c = paint(&big, 10, 6);
    for y in 0..6 {
        for x in 0..10 {
            assert_eq!(c.below().pixel(x, y), px(x as u32, y as u32));
        }
    }
}

#[test]
fn sp25_crop_at_decode() {
    let tmp = tempfile::tempdir().unwrap();
    let px = |x: u32, y: u32| 0xFF00_0000 | ((x & 0xFFF) << 12) | (y & 0xFFF);
    write(&tmp.path().join("wide.tga"), &tga32(5000, 8, true, px));
    write(&tmp.path().join("tall.tga"), &tga32(8, 5000, false, px));
    // 24-bit: an uncompressed 32-bit 4,096 × 4,096 TGA is 18 bytes over D4's 64 MiB file
    // limit (OPEN noted in skin-definition.md SP25).
    write(
        &tmp.path().join("ok.tga"),
        &tga_raw(4096, 4096, 24, 2, &[0x56; 4096 * 4096 * 3]),
    );
    write(
        &tmp.path().join("limit.tga"),
        &tga_solid(4096, 4096, 0xFF12_3456),
    );
    write(
        &tmp.path().join("huge.tga"),
        &tga_raw(16385, 1, 32, 2, &[0; 16385 * 4]),
    );
    let load = |n: &str| skin_file(tmp.path(), n, None).unwrap().load();
    let wide = load("wide.tga").unwrap();
    assert_eq!((wide.width(), wide.height()), (4096, 8));
    assert!(wide.is_cropped());
    for (x, y) in [(0, 0), (4095, 7), (1234, 3)] {
        assert_eq!(wide.pixel(x, y), Some(px(x, y)));
    }
    let tall = load("tall.tga").unwrap();
    assert_eq!((tall.width(), tall.height()), (8, 4096));
    // The displayed rows 0–4,095 (file rows 4,999 down to 904).
    assert_eq!(tall.pixel(3, 0), Some(px(3, 0)));
    assert_eq!(tall.pixel(3, 4095), Some(px(3, 4095)));
    let ok = load("ok.tga").unwrap();
    assert_eq!((ok.width(), ok.height()), (4096, 4096));
    assert!(!ok.is_cropped());
    assert!(matches!(
        load("limit.tga"),
        Err(SkinImageError::FileTooLarge { .. })
    ));
    assert!(matches!(
        load("huge.tga"),
        Err(SkinImageError::Decode(UiImageError::BadDimensions { .. }))
    ));
    // Drawn on an element 5,000 pixels wide, column 4,096 shows image column 0.
    let wide = Arc::new(wide);
    let c = paint(&wide, 5000, 8);
    assert_eq!(c.below().pixel(4096, 2), px(0, 2));
}

#[test]
fn sp26_source_format_tags() {
    let tmp = tempfile::tempdir().unwrap();
    let cases: Vec<(&str, Vec<u8>, SourceTag, u32)> = vec![
        (
            "a32.tga",
            tga_solid(1, 1, 0x8011_2233),
            SourceTag::Argb32,
            0x8011_2233,
        ),
        (
            "b24.tga",
            tga_raw(1, 1, 24, 2, &[0x33, 0x22, 0x11]),
            SourceTag::NoAlpha,
            0xFF11_2233,
        ),
        (
            "c8.tga",
            tga_raw(1, 1, 8, 3, &[0x80]),
            SourceTag::AlphaOnly,
            0x8000_0000,
        ),
        (
            "d16.tga",
            tga_raw(1, 1, 16, 2, &[0x00, 0x80]),
            SourceTag::Other,
            0xFF00_0000,
        ),
        (
            "e15.tga",
            tga_raw(1, 1, 15, 2, &[0xFF, 0x7F]),
            SourceTag::NoAlpha,
            0xFFFF_FFFF,
        ),
    ];
    for (name, bytes, tag, pixel) in cases {
        write(&tmp.path().join(name), &bytes);
        let img = skin_file(tmp.path(), name, None).unwrap().load().unwrap();
        assert_eq!((img.tag(), img.pixel(0, 0)), (tag, Some(pixel)), "{name}");
    }
    write(
        &tmp.path().join("x.dds"),
        &dds(4, 4, 0, 0x4, b"DXT1", 0, [0; 4], &[0; 8]),
    );
    let img = skin_file(tmp.path(), "x.dds", None)
        .unwrap()
        .load()
        .unwrap();
    assert_eq!(img.tag(), SourceTag::Other);
}

#[test]
fn sp27_pending_is_not_failed() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="S"/><Mapping ArtAssetID="Frame_TopLeft" FileName="f.tga"/></opt>"#,
    );
    write(&tmp.path().join("S/f.tga"), &tga_solid(2, 2, 0xFFAA_BBCC));
    let mut sel = selection(tmp.path());
    let overlay = sel.apply_option("S").current.unwrap();
    let ImageChoice::SkinFile(r) = overlay.resolve_image(DID_FRAME) else {
        panic!()
    };
    let mut ledger = SkinFileLedger::new();
    let LoadRequest::Schedule(ticket) = ledger.request(r) else {
        panic!("first request schedules")
    };
    // While the worker holds the decode back, a second element waits: no placeholder.
    assert_eq!(ledger.request(r), LoadRequest::Pending);
    let file = r.file.as_ref().unwrap();
    let img = file.load_with(overlay.dir_index());
    assert!(ledger.complete(file, ticket, img.as_ref().map(|_| ())));
    assert_eq!(ledger.request(r), LoadRequest::Ready);
    assert_eq!(img.unwrap().pixel(1, 1), Some(0xFFAA_BBCC));
}

#[test]
fn sp28_failed_loads_are_remembered_and_logged_once() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="S"/><Mapping ArtAssetID="Frame_TopLeft" FileName="late.tga"/></opt>"#,
    );
    let mut sel = selection(tmp.path());
    let overlay = sel.apply_option("S").current.unwrap();
    let ImageChoice::SkinFile(r) = overlay.resolve_image(DID_FRAME) else {
        panic!()
    };
    let file = r.file.as_ref().unwrap();
    let mut ledger = SkinFileLedger::new();
    let ((), warnings) = WarnCounter::run(|| {
        let LoadRequest::Schedule(ticket) = ledger.request(r) else {
            panic!("first request schedules")
        };
        let e = file.load().unwrap_err();
        assert!(ledger.complete(file, ticket, Err(&e)));
        assert_eq!(ledger.request(r), LoadRequest::Placeholder);
        // The file appears; the first element and a second one still get the placeholder.
        write(
            &tmp.path().join("S/late.tga"),
            &tga_solid(2, 2, 0xFF01_0203),
        );
        assert_eq!(ledger.request(r), LoadRequest::Placeholder);
        assert_eq!(ledger.request(r), LoadRequest::Placeholder);
    });
    assert_eq!(warnings, 1);
    // Deactivate and activate again: a fresh ledger, and the file loads.
    sel.deactivate();
    let overlay = sel.apply_option("S").current.unwrap();
    ledger.clear();
    let ImageChoice::SkinFile(r) = overlay.resolve_image(DID_FRAME) else {
        panic!()
    };
    assert!(matches!(ledger.request(r), LoadRequest::Schedule(_)));
    assert!(r.file.as_ref().unwrap().load().is_ok());
}

/// A load scheduled before a switch that reports after it must not decide the new
/// activation (§6.6, D27, SP28).
#[test]
fn sp28_late_results_from_before_a_switch_are_ignored() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="S"/><Mapping ArtAssetID="Frame_TopLeft" FileName="a.tga"/></opt>"#,
    );
    let mut sel = selection(tmp.path());
    let overlay = sel.apply_option("S").current.unwrap();
    let ImageChoice::SkinFile(r) = overlay.resolve_image(DID_FRAME) else {
        panic!()
    };
    let file = r.file.as_ref().unwrap();
    let mut ledger = SkinFileLedger::new();
    let LoadRequest::Schedule(old) = ledger.request(r) else {
        panic!()
    };
    let stale = file.load_with(overlay.dir_index()).unwrap_err();
    // The switch happens while the worker still holds the failure.
    sel.deactivate();
    let overlay = sel.apply_option("S").current.unwrap();
    ledger.clear();
    write(&tmp.path().join("S/a.tga"), &tga_solid(1, 1, 0xFF11_2233));
    assert!(!ledger.complete(file, old, Err(&stale)));
    let ImageChoice::SkinFile(r) = overlay.resolve_image(DID_FRAME) else {
        panic!()
    };
    let LoadRequest::Schedule(new) = ledger.request(r) else {
        panic!("the repaired file is read anew after the switch")
    };
    let file = r.file.as_ref().unwrap();
    let img = file.load_with(overlay.dir_index()).unwrap();
    assert!(ledger.complete(file, new, Ok(())));
    assert_eq!(ledger.request(r), LoadRequest::Ready);
    assert_eq!(img.pixel(0, 0), Some(0xFF11_2233));
}

/// D2, §6.6: two spellings share one key, so they must open one file, the entry that sorts
/// first by byte value, whichever is asked first.
#[test]
fn d2_spellings_of_one_key_open_one_file() {
    let tmp = tempfile::tempdir().unwrap();
    let skin = tmp.path().join("skin");
    write(&skin.join("A.tga"), &tga_solid(1, 1, 0xFFFF_0000));
    write(&skin.join("a.tga"), &tga_solid(1, 1, 0xFF00_00FF));
    write(&skin.join("Art/x.tga"), &tga_solid(1, 1, 0xFF00_FF00));
    write(&skin.join("art/x.tga"), &tga_solid(1, 1, 0xFF00_0001));
    let both_case_sensitive = std::fs::read_dir(&skin).unwrap().count() == 3 + 1;
    if !both_case_sensitive {
        eprintln!("case-insensitive file system; nothing to check");
        return;
    }
    for (a, b) in [("A.tga", "a.tga"), ("art/x.tga", "ART\\X.TGA")] {
        let fa = skin_file(&skin, a, None).unwrap();
        let fb = skin_file(&skin, b, None).unwrap();
        assert_eq!(fa.cache_key(), fb.cache_key());
        assert_eq!(fa.resolve_on_disk(), fb.resolve_on_disk(), "{a} / {b}");
        assert_eq!(
            fa.load().unwrap().pixel(0, 0),
            fb.load().unwrap().pixel(0, 0)
        );
    }
    // The byte-smallest entry wins: `A.tga` (0x41 < 0x61) and the folder `Art`.
    let f = skin_file(&skin, "a.tga", None).unwrap();
    assert_eq!(f.load().unwrap().pixel(0, 0), Some(0xFFFF_0000));
    let f = skin_file(&skin, "art/x.tga", None).unwrap();
    assert_eq!(f.load().unwrap().pixel(0, 0), Some(0xFF00_FF00));
}

/// A named pipe as a skin file fails at once instead of blocking the asset worker.
#[cfg(unix)]
#[test]
fn fifo_skin_file_does_not_block() {
    let tmp = tempfile::tempdir().unwrap();
    let fifo = tmp.path().join("p.tga");
    let made = std::process::Command::new("mkfifo")
        .arg(&fifo)
        .status()
        .is_ok_and(|s| s.success());
    if !made {
        eprintln!("mkfifo unavailable; skipping");
        return;
    }
    let file = skin_file(tmp.path(), "p.tga", None).unwrap();
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let _ = tx.send(file.load());
    });
    let r = rx
        .recv_timeout(std::time::Duration::from_secs(10))
        .expect("loading a FIFO blocked");
    assert!(matches!(r, Err(SkinImageError::Io(_))), "{r:?}");
}

/// Activation does no file-system work for drive-letter names (D12): thousands of
/// mappings into a large real folder through the prefix finish at once.
#[test]
fn activation_with_many_drive_letter_mappings_is_lexical() {
    let tmp = tempfile::tempdir().unwrap();
    let mut xml = String::from("<opt><SkinName Name=\"S\"/>");
    let mut arts = Vec::new();
    for i in 0..4_000u32 {
        let label = format!("Art_{i}");
        xml.push_str(&format!(
            "<Mapping ArtAssetID=\"{label}\" FileName=\"Z:\\USR\\SHARE\\X{i}.tga\"/>"
        ));
        arts.push((label, 0x2000_0000 + i));
    }
    xml.push_str("</opt>");
    write(&tmp.path().join("S/SkinDefinition.xml"), xml.as_bytes());
    let pairs: Vec<(&str, u32)> = arts.iter().map(|(l, k)| (l.as_str(), *k)).collect();
    let (art_assets, elements) = resolver(&pairs, &[]);
    let t = SkinTables {
        art_assets,
        elements,
        ..SkinTables::default()
    };
    let set = SkinSet::discover(tmp.path(), &t);
    let env = SkinEnvironment {
        wine_prefix: Some(tmp.path().join("prefix")),
    };
    let mut sel = SkinSelection::new(Arc::new(set), Arc::new(t), env);
    let started = std::time::Instant::now();
    let overlay = sel.apply_option("S").current.unwrap();
    let took = started.elapsed();
    assert_eq!(overlay.replacements().len(), 4_000);
    assert_eq!(
        overlay.dir_index().folders(),
        0,
        "no folder listed at activation"
    );
    assert!(
        took < std::time::Duration::from_secs(2),
        "activation took {took:?}"
    );
    let f = overlay
        .replacement(0x2000_0007)
        .unwrap()
        .file
        .as_ref()
        .unwrap();
    assert!(
        f.cache_key().ends_with("/dosdevices/z:/usr/share/x7.tga"),
        "{}",
        f.cache_key()
    );
}

#[test]
fn d2_letter_case_d7_dispatch_d12_drive_letters() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("skin/art/frame.tga"),
        &tga_solid(1, 1, 0xFF00_FF00),
    );
    let f = skin_file(&tmp.path().join("skin"), "ART\\Frame.TGA", None).unwrap();
    assert_eq!(f.load().unwrap().pixel(0, 0), Some(0xFF00_FF00));
    // Two spellings share one cache key (§6.6).
    let g = skin_file(&tmp.path().join("skin"), "art/FRAME.tga", None).unwrap();
    assert_eq!(f.cache_key(), g.cache_key());
    assert_eq!(f.image_key(), g.image_key());
    // D7 and D15: only the final extension decides; `.iff`, `.png`, `.jpeg` fail.
    write(&tmp.path().join("skin/a.tga.png"), &tga_solid(1, 1, 0));
    for name in ["a.tga.png", "x.iff", "x.jpeg"] {
        let r = skin_file(&tmp.path().join("skin"), name, None)
            .unwrap()
            .load();
        assert!(
            matches!(
                r,
                Err(SkinImageError::Decode(
                    UiImageError::UnsupportedFileType { .. }
                ))
            ),
            "{name}: {r:?}"
        );
    }
    // D12: a drive-letter name maps through the Wine prefix; without one it fails.
    let prefix = tmp.path().join("prefix");
    write(
        &prefix.join("drive_c/users/steamuser/pic.tga"),
        &tga_solid(1, 1, 0xFF0A_0B0C),
    );
    let f = skin_file(
        Path::new("/unused"),
        "C:\\users\\steamuser\\pic.tga",
        Some(&prefix),
    )
    .unwrap();
    assert_eq!(f.load().unwrap().pixel(0, 0), Some(0xFF0A_0B0C));
    assert!(matches!(
        skin_file(Path::new("/unused"), "C:\\pic.tga", None),
        Err(SkinPathError::UnmappedDrive(_))
    ));
    assert_eq!(
        skin_file(
            Path::new("/unused"),
            "//server/share/pic.tga",
            Some(&prefix)
        ),
        Err(SkinPathError::NetworkPath)
    );
}

#[test]
fn files_and_replacements_of_an_overlay() {
    let tmp = tempfile::tempdir().unwrap();
    write(
        &tmp.path().join("S/SkinDefinition.xml"),
        br#"<opt><SkinName Name="S"/>
            <Mapping ArtAssetID="Frame_TopLeft" FileName="Shared.tga"/>
            <Mapping ArtAssetID="Button_Normal" FileName="shared.TGA"/>
            <Mapping ArtAssetID="Other_Art" FileName="\\net\x.tga"/></opt>"#,
    );
    let mut sel = selection(tmp.path());
    let overlay = sel.apply_option("S").current.unwrap();
    assert_eq!(overlay.replacements().len(), 3);
    assert_eq!(
        overlay.files().len(),
        1,
        "one file under one lower-cased key"
    );
    let r = overlay.replacement(ART_OTHER).unwrap();
    assert_eq!(r.file, Err(SkinPathError::NetworkPath));
    let mut ledger = SkinFileLedger::new();
    assert_eq!(ledger.request(r), LoadRequest::Placeholder);
}
